import numpy as np
from scipy.optimize import least_squares
from scipy.spatial.transform import Rotation
O=np.array([[.005,.155,.43],[0,.214,.439],[0,.214,.305],[.018,.214,.107],[.188,.214,.077]],float);A=np.array([[0,.906,.423],[1,0,0],[0,0,1],[0,1,0],[1,0,0]],float)
def fk(q):
 p=list(O.copy())+[np.array([.41,.214,.087])];Q=np.eye(3)
 for j,t in enumerate(q):
  ax=Q@A[j];R=Rotation.from_rotvec(ax/np.linalg.norm(ax)*t).as_matrix();c=p[j];p[j:]=[c+R@(v-c) for v in p[j:]];Q=R@Q
 return p[-1]
for tgt in [[.55,-.2,-.15],[.55,-.3,-.15],[.6,-.3,-.15],[.6,-.4,-.15]]:
 for x0 in [[-.4,-.2,-.5,1.2,0],[-.8,-.3,-1.,1.4,0]]:
  r=least_squares(lambda q: fk(q)-np.array(tgt),x0,bounds=([-2.87,-.34,-1.3,-1.25,-.15],[2.87,3.11,4.45,2.61,1.57]),max_nfev=2000)
  if np.linalg.norm(r.fun)<0.2: print(tgt,np.round(r.x,2),np.round(fk(r.x),2), round(np.linalg.norm(r.fun),2))
